import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2

    edges = defaultdict(list)
    degree = [0] * (n + 1)

    for _ in range(m):
        u = int(input[index])
        v = int(input[index + 1])
        edges[u].append(v)
        edges[v].append(u)
        degree[u] += 1
        degree[v] += 1
        index += 2

    if any(d % 2 != 0 for d in degree):
        print("No solution")
        return

    visited = [False] * (m + 1)
    result = []

    def find_path(start, prev_edge):
        current = start
        path = []
        while True:
            found = False
            for neighbor in edges[current]:
                edge_index = min((u, v) for u, v in ((current, neighbor), (neighbor, current)))
                if not visited[edge_index]:
                    visited[edge_index] = True
                    path.append((current, neighbor))
                    current = neighbor
                    found = True
                    break
            if not found:
                break
        return path

    for node in range(1, n + 1):
        if degree[node] > 0:
            for neighbor in edges[node]:
                edge_index = min((node, neighbor), (neighbor, node))
                if not visited[edge_index]:
                    path = find_path(node, edge_index)
                    for i in range(len(path) - 1):
                        u, v = path[i]
                        x, y = path[i + 1]
                        if v == x:
                            result.append((u, v, y))
                        else:
                            result.append((u, v, x))

    if len(result) == m // 2:
        for u, v, w in result:
            print(u, v, w)
    else:
        print("No solution")

if __name__ == "__main__":
    main()
